// =============================================================================
// SCOUT
// =============================================================================

/**
 * Primary specialization domains.
 *  - youth:      players under 21; better at reading potential over CA
 *  - firstTeam:  ready-now players; focus on current ability accuracy
 *  - regional:   deep knowledge of one geographic territory
 *  - data:       statistical analysis; unlocks data overlays on reports
 */
export type Specialization = "youth" | "firstTeam" | "regional" | "data";

/**
 * Scout skills — determine accuracy and depth of attribute assessments.
 *  - technicalEye:          reading technical attributes
 *  - physicalAssessment:    reading physical attributes
 *  - psychologicalRead:     reading mental and hidden attributes
 *  - tacticalUnderstanding: reading tactical attributes
 *  - dataLiteracy:          interpreting statistics (data specialization perk)
 */
export type ScoutSkill =
  | "technicalEye"
  | "physicalAssessment"
  | "psychologicalRead"
  | "tacticalUnderstanding"
  | "dataLiteracy"
  | "playerJudgment"
  | "potentialAssessment";

/**
 * Scout personal attributes that affect career mechanics.
 *  - networking:    unlocks contacts faster, improves contact quality
 *  - persuasion:    amplifies conviction level impact on club decisions
 *  - endurance:     reduces fatigue accumulation per activity
 *  - adaptability:  reduces accuracy penalty in unfamiliar regions
 *  - memory:        retains more detail from video analysis sessions
 *  - intuition:     chance of detecting hidden attributes without indicators
 */
export type ScoutAttribute =
  | "networking"
  | "persuasion"
  | "endurance"
  | "adaptability"
  | "memory"
  | "intuition";

/**
 * Career progression ladder.
 *  1 = Freelance scout (no club, self-employed)
 *  2 = Part-time regional scout
 *  3 = Full-time club scout
 *  4 = Head of scouting / chief scout
 *  5 = Director of football / sporting director
 */
export type CareerTier = 1 | 2 | 3 | 4 | 5;

export interface PendingInsightReportQualityEffect {
  id: string;
  actionId: "theVerdict";
  playerId?: string;
  bonusPoints: number;
  sourceSessionId: string;
  createdWeek: number;
  createdSeason: number;
}

export interface PendingInsightQueryAccuracyEffect {
  id: string;
  actionId: "algorithmicEpiphany";
  leagueId?: string;
  accuracyBonus: number;
  sourceSessionId: string;
  createdWeek: number;
  createdSeason: number;
}

/** Deferred, single-use Insight effects that survive save/load. */
export interface InsightPersistedEffects {
  pendingReportQuality: PendingInsightReportQualityEffect[];
  pendingQueryAccuracy: PendingInsightQueryAccuracyEffect[];
}

/** Insight Points state — tracks the scout's eureka-moment resource. */
export interface InsightState {
  /** Current insight points. */
  points: number;
  /** Maximum storable IP (40 base + intuition × 2). */
  capacity: number;
  /** Weeks remaining before next insight use is allowed. */
  cooldownWeeksRemaining: number;
  /** Total insight actions used in career. */
  lifetimeUsed: number;
  /** Total IP earned in career. */
  lifetimeEarned: number;
  /** Game week when an insight was last used. */
  lastUsedWeek: number;
  /** History of insight uses. */
  history: InsightUseRecord[];
  /** Deferred effects waiting for their matching report or data query. */
  persistedEffects?: InsightPersistedEffects;
}

/** Record of a single insight action use. */
export interface InsightUseRecord {
  actionId: string;
  week: number;
  season: number;
  targetPlayerId?: string;
  outcome: "valuable" | "moderate" | "wasted";
  narrative: string;
}

export interface HomeBaseRelocationRecord {
  id: string;
  fromCountry: string;
  toCountry: string;
  week: number;
  season: number;
  cost: number;
  /** Satellite office converted into the new permanent base. */
  convertedOfficeId: string;
}

export interface Scout {
  id: string;
  firstName: string;
  lastName: string;
  age: number;
  /** Scout's nationality (flavour / display field, not mechanically enforced). */
  nationality?: string;
  /**
   * Permanent operating base. Unlike familiarity, this does not silently move
   * when the scout becomes more knowledgeable in another country.
   */
  homeCountry?: string;
  /** Bounded history of deliberate, costly agency-base moves. */
  homeBaseRelocations?: HomeBaseRelocationRecord[];
  /** Selected portrait avatar (1-6). */
  avatarId?: number;

  /** Scout skill ratings on 1–20 scale. */
  skills: Record<ScoutSkill, number>;
  /** Scout personal attribute ratings on 1–20 scale. */
  attributes: Record<ScoutAttribute, number>;

  primarySpecialization: Specialization;
  secondarySpecialization?: Specialization;
  /** Depth of mastery within the primary specialization, 1–20. */
  specializationLevel: number;
  /** Progress toward the next specialization level. */
  specializationXp: number;
  /**
   * IDs of unlocked specialization perks.
   * Examples: "youthEye", "dataDriven", "setpieceReader", "mentorNetwork"
   */
  unlockedPerks: string[];

  careerTier: CareerTier;
  /** Whether the scout is on the club or independent career path. */
  careerPath: CareerPath;
  /**
   * Whether the player has deliberately committed to a career path.
   *
   * Fresh freelance careers begin on the independent operating model so they
   * can earn money, but that default must not silently count as the permanent
   * club-vs-independent career decision.
   */
  careerPathChosen?: boolean;
  /** Independent path tier (only used when careerPath === "independent"). */
  independentTier?: IndependentTier;
  /** Global scouting reputation, 0–100. Determines job offer quality. */
  reputation: number;
  /** Trust level with current employer club, 0–100. Affects report weight. */
  clubTrust: number;
  /** Reputation within the scout's specialization community, 0–100. */
  specializationReputation: number;

  currentClubId?: string;
  contractEndSeason?: number;
  /** Weekly employment salary, following UK football convention. */
  salary: number;
  /** Current employment terms. Legacy saves may only have the fields above. */
  employmentContract?: ScoutEmploymentContract;
  /** @deprecated Liquid cash is owned by `FinancialRecord.balance`. */
  savings: number;

  // Lifetime career statistics
  reportsSubmitted: number;
  successfulFinds: number;
  /** IDs of players the scout discovered before any other scout. */
  discoveryCredits: string[];

  /**
   * Fatigue level 0–100.
   * High fatigue reduces observation accuracy and report quality.
   * Recovered via rest activities or natural end-of-week recovery.
   */
  fatigue: number;

  /** Accumulated XP toward next skill level-up. Threshold = currentLevel * 10. */
  skillXp: Partial<Record<ScoutSkill, number>>;
  /** Accumulated XP toward next attribute level-up. Threshold = currentLevel * 10. */
  attributeXp: Partial<Record<ScoutAttribute, number>>;
  /** Insight Points state for eureka-moment actions. */
  insightState?: InsightState;

  // --- Phase 1 extensions ---

  /** IDs of NPC scouts managed by the player (tier 4+). */
  npcScoutIds: string[];
  /** Per-country reputation tracking. */
  countryReputations: Record<string, CountryReputation>;
  /** Relationship with the current club's manager. */
  managerRelationship?: ManagerRelationship;
  /** Active board directives from the club hierarchy (tier 5). */
  boardDirectives: BoardDirective[];
  /** Current international travel booking (null if at home). */
  travelBooking?: TravelBooking;

  // --- Deep Systems Overhaul ---
  /** Rolling accuracy tracking for recent reports. */
  accuracyHistory?: { week: number; season: number; predictedCA: number; actualCA: number }[];
  /** Monthly performance pulse grades. */
  performancePulses?: PerformancePulse[];
}

// =============================================================================
// PERCEPTION & OBSERVATIONS
// =============================================================================

export type ObservationContext =
  | "liveMatch"
  | "videoAnalysis"
  | "trainingGround"
  | "youthTournament"
  | "academyVisit"
  | "schoolMatch"
  | "grassrootsTournament"
  | "streetFootball"
  | "academyTrialDay"
  | "youthFestival"
  | "followUpSession"
  | "parentCoachMeeting"
  // First-team exclusive contexts
  | "reserveMatch"
  | "oppositionAnalysis"
  | "agentShowcase"
  | "trialMatch"
  // Data-exclusive contexts
  | "databaseQuery"
  | "statsBriefing"
  | "deepVideoAnalysis";

export interface FlaggedMoment {
  /** Minute or phase index when this notable moment occurred. */
  phase: number;
  description: string;
  attribute: PlayerAttribute;
  positive: boolean;
}

/**
 * A single attribute reading within one observation session.
 * Perceived value and confidence are biased by scout skill, fatigue,
 * and contextual multipliers.
 */
export interface AttributeReading {
  attribute: PlayerAttribute;
  /** Scout's estimate on 1–20 scale (may differ from true value). */
  perceivedValue: number;
  /** Certainty in this reading, 0–1. */
  confidence: number;
  /** Number of separate sessions contributing to this reading. */
  observationCount: number;
  /** Lower bound of estimated range (1–20). Undefined in old saves. */
  rangeLow?: number;
  /** Upper bound of estimated range (1–20). Undefined in old saves. */
  rangeHigh?: number;
}

export interface Observation {
  id: string;
  playerId: string;
  scoutId: string;
  /** Interactive session that produced this evidence, when applicable. */
  sourceSessionId?: string;
  /** Scheduled activity instance that produced this evidence. */
  activityInstanceId?: string;
  /** Set when context is liveMatch; references the Fixture id. */
  matchId?: string;
  week: number;
  season: number;
  context: ObservationContext;
  attributeReadings: AttributeReading[];
  /** Narrative notes generated by the perception engine. */
  notes: string[];
  flaggedMoments: FlaggedMoment[];
  /** The focus lens used during this observation, if any. Omitted for general/unfocused. */
  focusLens?: "technical" | "physical" | "mental" | "tactical";
  /** Explainable, idempotent regional context applied when evidence was filed. */
  regionalContext?: import("../world/regionalPresence").RegionalObservationContext;
  /**
   * Persisted, player-visible conditions that shaped this evidence. Optional
   * for legacy saves and deliberately contains no hidden player truth.
   */
  situation?: import("../observation/situations").ObservationSituationSnapshot;
  abilityReading?: AbilityReading;
  /**
   * A personality trait uncovered during this observation session.
   * Set by the perception engine when the reveal roll succeeds.
   * Callers should add this to player.personalityRevealed in game state.
   */
  revealedPersonalityTrait?: PersonalityTrait;
  /**
   * A behavioral trait uncovered during this observation session.
   * Callers should add this to player.playerTraitsRevealed in game state.
   */
  revealedPlayerTrait?: PlayerTrait;
  /**
   * Role suitability inferences from this observation, if enough data exists.
   */
  inferredRoleFit?: Array<{ role: PlayerRole; suitability: number }>;
  /**
   * Updated personality profile after progressive reveal during this observation.
   * Callers should apply this to player.personalityProfile in game state.
   */
  updatedPersonalityProfile?: PersonalityProfile;
}

export interface AbilityReading {
  perceivedCA: number;       // 0.5-5.0 star rating
  caConfidence: number;      // 0-1
  perceivedPALow: number;   // PA range lower bound (0.5-5.0)
  perceivedPAHigh: number;  // PA range upper bound (0.5-5.0)
  paConfidence: number;     // 0-1
}

// =============================================================================
// REPORTS
// =============================================================================

/**
 * How strongly the scout recommends acquisition.
 *  - note:             "worth monitoring in future"
 *  - recommend:        "we should consider this player"
 *  - strongRecommend:  "sign this player soon"
 *  - tablePound:       "I stake my reputation — sign now"
 *                      (tablePounds are a limited career resource per season)
 */
export type ConvictionLevel =
  | "note"
  | "recommend"
  | "strongRecommend"
  | "tablePound";

export interface AttributeAssessment {
  attribute: PlayerAttribute;
  /** Scout's best point estimate of the true attribute value (1–20). */
  estimatedValue: number;
  /**
   * Confidence interval, e.g. [13, 16].
   * Narrower = higher accuracy. Width driven by observationCount and skill.
   */
  confidenceRange: [number, number];
  domain: AttributeDomain;
}

export interface ScoutReport {
  id: string;
  /** Stable causal case that owns every revision, delivery, and later outcome. */
  caseId?: string;
  /** Recruitment brief this report is answering, when one exists. */
  briefId?: string;
  /** Prior immutable report revision superseded by this judgment. */
  supersedesReportId?: string;
  /** Monotonic revision number within the scouting case. */
  revision?: number;
  playerId: string;
  scoutId: string;
  submittedWeek: number;
  submittedSeason: number;
  /** Observation records consumed by this immutable report revision. */
  evidenceObservationIds?: string[];
  /** Scheduled desk preparation consumed by this authored revision. */
  preparationWorkItemId?: string;

  attributeAssessments: AttributeAssessment[];
  strengths: string[];
  weaknesses: string[];
  conviction: ConvictionLevel;
  /** Free-text narrative written by the scout. */
  summary: string;
  /**
   * Canonical evidence-backed judgment. The summary above is a generated
   * presentation of this state for new reports and a legacy display field for
   * older saves.
   */
  evidenceAssessment?: StructuredScoutingAssessment;
  /** Optional private notebook text. It is never scored or parsed by gameplay. */
  privateNotes?: string[];
  /** ID of a known player the scout compares the subject to. */
  comparisonPlayerId?: string;
  estimatedValue: number;
  /** Optional bounded value range when the report carries material uncertainty. */
  estimatedValueRange?: [number, number];

  /** Structured professional context for reports authored under youth EA. */
  intendedClubId?: string;
  intendedAudience?: "academyDirector" | "headOfRecruitment" | "sportingDirector" | "client";
  /** How the scout chose to frame the case to its intended decision-maker. */
  presentationApproach?: YouthPresentationApproach;
  recruitmentNeed?: string;
  projectedRole?: PlayerRole;
  recommendedAction?: ReportRecommendedAction;
  riskFactors?: string[];
  riskAssessments?: ReportRiskAssessment[];
  estimatedWeeklyWage?: number;
  decisionDeadlineWeek?: number;
  decisionDeadlineSeason?: number;
  categoryVerdicts?: Partial<Record<JudgmentCategory, ReportCategoryVerdict>>;
  alternativePlayerIds?: string[];

  /**
   * Composite quality score 0–100.
   * Driven by scout skill, observation count, and confidence range widths.
   */
  qualityScore: number;

  /** Reputation change when this report was submitted. */
  reputationDelta?: number;
  /** Reputation change applied when the report was retrospectively validated. */
  accuracyReputationDelta?: number;

  /** Club's subsequent decision on the scouted player. */
  clubResponse?: "ignored" | "shortlisted" | "signed";
  /**
   * Retrospective accuracy rating set after a transfer completes, 0–100.
   * Compares report assessments to actual player attribute values.
   */
  postTransferRating?: number;

  /** Perceived current ability in half-star rating (0.5-5.0). */
  perceivedCAStars?: number;
  /** Perceived potential ability range in half-star ratings [low, high]. */
  perceivedPARange?: [number, number];

  /** System fit score for first-team scouts (0-100). */
  systemFitScore?: number;
  /** Statistical highlights for data scouts. */
  statisticalHighlights?: string[];
  /** Breakdown of the quality score into component parts. */
  qualityBreakdown?: {
    accuracy: number;
    coverage: number;
    conviction: number;
    tightness: number;
    personalityBonus: number;
    equipmentBonus: number;
  };
  /** Evidence-facing craftsmanship breakdown used by newly submitted reports. */
  craftBreakdown?: {
    observationDepth: number;
    confidenceLevel: number;
    convictionFit: number;
    detail: number;
    scoutSkill: number;
    equipmentBonus: number;
    /** Bounded craft contribution from one consumed, player-visible analyst review. */
    analystReviewBonus?: number;
  };
  /** Immutable snapshot of the analyst advice incorporated into this revision. */
  analystReview?: AppliedAnalystReview;
  /**
   * Engine-only truth snapshot for the attributes assessed when the report was
   * submitted. It is never rendered; delayed validation uses it so natural
   * player development is not mistaken for an inaccurate original report.
   */
  validationSnapshot?: Partial<Record<PlayerAttribute, number>>;
}

/**
 * Prepared desk work created by a scheduled report-writing block.
 *
 * It is deliberately not a ScoutReport: scheduling can organize evidence and
 * improve craft, but the player must still make and submit every judgment.
 */
export interface ReportWorkItem {
  id: string;
  playerId: string;
  scoutId: string;
  createdWeek: number;
  createdSeason: number;
  status: "ready" | "consumed";
  sourceActivity: "writeReport";
  /** Bounded additive craft points earned through focused preparation. */
  preparationQualityPoints: number;
  /** Equipment preparation bonus retained until the report is submitted. */
  preparationQualityBonus: number;
  freshObservationIds: string[];
  consumedByReportId?: string;
}

/** The persistent spine that connects a discovery opinion to its consequences. */
export type ScoutingCaseStatus =
  | "open"
  | "reported"
  | "delivered"
  | "placed"
  | "closed";

/** Player-visible professional question that gives a scouting case its shape. */
export interface ProfessionalCaseContext {
  modeId: GameModeId;
  familyId: string;
  title: string;
  premise: string;
  centralQuestion: string;
  stakeholderRefs: string[];
  judgmentDecisionIds: string[];
}

export interface ScoutingCase {
  id: string;
  playerId: string;
  scoutId: string;
  openedWeek: number;
  openedSeason: number;
  lastUpdatedWeek: number;
  lastUpdatedSeason: number;
  status: ScoutingCaseStatus;
  /** Optional for legacy cases; new evergreen cases persist their authored frame. */
  professionalContext?: ProfessionalCaseContext;
  /** Club need that opened this case. */
  briefId?: string;
  /** Durable journal hypothesis ids considered in this case. */
  hypothesisIds?: string[];
  /** Latest report revision in the case. */
  activeReportId?: string;
  reportIds: string[];
  listingIds: string[];
  deliveryIds: string[];
  decisionIds: string[];
  placementReportIds: string[];
  /** Long-horizon review records generated from the recommendation. */
  reviewIds?: string[];
  alumniRecordId?: string;
  /** True when a legacy placement had no authored scout report to link. */
  legacyUnlinked?: boolean;
}

export type ReportDeliveryChannel = "marketplaceSale" | "directPlacement";
export type ReportDeliveryStatus = "delivered" | "awaitingDecision" | "resolved";

/** An immutable record of report intelligence reaching a particular audience. */
export interface ReportDelivery {
  id: string;
  caseId: string;
  /** Optional only for legacy placements that predate authored reports. */
  reportId?: string;
  clubId: string;
  channel: ReportDeliveryChannel;
  status: ReportDeliveryStatus;
  deliveredWeek: number;
  deliveredSeason: number;
  listingId?: string;
  bidId?: string;
  placementReportId?: string;
  price?: number;
  decisionId?: string;
  resolvedWeek?: number;
  resolvedSeason?: number;
}

export type ClubDecisionOutcome = "accepted" | "rejected" | "trial" | "followUpRequested";

/** A club's persisted response to a specific delivery, resolved exactly once. */
export interface ClubDecision {
  id: string;
  caseId: string;
  deliveryId: string;
  reportId?: string;
  clubId: string;
  recruitmentSnapshot?: import("../world/recruitmentIdentity").HistoricalRecruitmentDoctrineSnapshot;
  outcome: ClubDecisionOutcome;
  decidedWeek: number;
  decidedSeason: number;
  placementReportId?: string;
  reason?: string;
  /** Explainable reasons persisted at decision time; never recomputed from hidden truth. */
  reasons?: string[];
  scoreBreakdown?: {
    evidence: number;
    briefFit: number;
    affordability: number;
    conviction: number;
    risk: number;
    relationship: number;
    competition: number;
    /** Audience-and-brief alignment of the chosen report-room strategy. Optional for legacy decisions. */
    presentation?: number;
    /** Evidence-supported confidence rather than the scout's declared confidence alone. */
    calibration?: number;
    /** Visible registration, adaptation, family, and pathway context for youth moves. */
    mobility?: number;
    total: number;
  };
  requestedEvidenceCategory?: JudgmentCategory;
  followUpDueWeek?: number;
  followUpDueSeason?: number;
}

/** The three judgments a youth scout must support with different evidence. */
export type JudgmentCategory = "potential" | "roleFit" | "characterRisk";

/** Deliberate framing used when presenting a structured youth recommendation. */
export type YouthPresentationApproach = "evidenceLed" | "fitLed" | "riskLed";

export type ReportRecommendedAction =
  | "monitor"
  | "inviteForTrial"
  | "offerAcademyPlace";

export interface ReportCategoryVerdict {
  verdict: string;
  confidence: "low" | "medium" | "high";
  hypothesisIds: string[];
  /** Explicitly records what the scout still does not know. */
  acknowledgedUncertainty: string;
  /** Structured evidence authority for reports written after the evidence-RPG migration. */
  status?: "assessed" | "notAssessed";
  evidenceIds?: string[];
  classification?: EvidenceClassificationId;
  claimSupport?: StructuredClaimSupport;
  unknownOptionId?: string;
}

export type YouthReportRiskId =
  | "injuryAvailability"
  | "physicalDevelopment"
  | "pressureResponse"
  | "roleTranslation"
  | "adaptationMobility"
  | "competitionTranslation"
  | "noMaterialSignal";

export interface ReportRiskAssessment {
  id: YouthReportRiskId;
  label: string;
  status: "observed" | "untested" | "noSignal";
  evidenceIds: string[];
}

/** Player-authored professional context attached to a generated report draft. */
export interface StructuredReportInput {
  briefId: string;
  intendedClubId: string;
  intendedAudience: NonNullable<ScoutReport["intendedAudience"]>;
  /** Optional only for callers and saves created before presentation strategy existed. */
  presentationApproach?: YouthPresentationApproach;
  recruitmentNeed: string;
  projectedRole: PlayerRole;
  recommendedAction: ReportRecommendedAction;
  riskFactors: string[];
  estimatedWeeklyWage: number;
  decisionDeadlineWeek: number;
  decisionDeadlineSeason: number;
  categoryVerdicts: Record<JudgmentCategory, ReportCategoryVerdict>;
  alternativePlayerIds: string[];
  /** Present when the report was authored from deterministic evidence choices. */
  evidenceVersion?: 1;
  evidenceIds?: string[];
  riskAssessments?: ReportRiskAssessment[];
}

export type YouthBriefPriority =
  | "highCeiling"
  | "earlyReadiness"
  | "character"
  | "resale";

export interface YouthRecruitmentBrief {
  id: string;
  clubId: string;
  type: "academyPlacement";
  createdWeek: number;
  createdSeason: number;
  recruitmentSnapshot?: import("../world/recruitmentIdentity").HistoricalRecruitmentDoctrineSnapshot;
  expiresWeek: number;
  expiresSeason: number;
  requiredPositions: Position[];
  preferredRole?: PlayerRole;
  developmentPriority: YouthBriefPriority;
  maxAge: number;
  riskTolerance: "low" | "medium" | "high";
  weeklyWageBudget: number;
  sourceContactId?: string;
  /** Rising pressure makes waiting safer informationally but costlier competitively. */
  competitionPressure: number;
  status: "open" | "fulfilled" | "expired";
  assignedCaseId?: string;
  fulfilledByPlayerId?: string;
  /** Last strict settlement checks that prevented this accepted case from closing the brief. */
  fulfillmentFailures?: string[];
}

export type RecommendationReviewCheckpoint = "oneSeason" | "twoSeasons";

