export type ContactType =
  | "agent"
  | "scout"
  | "clubStaff"
  | "journalist"
  | "academyCoach"
  | "sportingDirector"
  | "grassrootsOrganizer"
  | "schoolCoach"
  | "youthAgent"
  | "academyDirector"
  | "localScout";

export interface Contact {
  id: string;
  name: string;
  type: ContactType;
  organization: string;
  /** Quality of relationship, 0–100. Higher = more willing to share info. */
  relationship: number;
  /**
   * How reliable the contact's tips are, 0–100.
   * Hidden from player initially; revealed through repeated interactions.
   */
  reliability: number;
  /** IDs of players this contact has information about. */
  knownPlayerIds: string[];
  /** Geographic region of expertise. */
  region?: string;
  /**
   * The country this contact primarily operates in.
   * Used for youth scouting intel and contact introductions.
   */
  country?: string;
  /** Last interaction date, used to calculate relationship decay across seasons. */
  lastInteractionAt?: GameDate;

  // --- F3: Contact Network Depth ---

  /** Trust level 0-100. Determines what information the contact will share. */
  trustLevel?: number;
  /** Hidden loyalty stat 0-100. Affects betrayal risk and gossip reliability. */
  loyalty?: number;
  /** History of interactions for trust/loyalty calculations. */
  interactionHistory?: ContactInteraction[];
  /** Pending gossip items this contact has to share. */
  gossipQueue?: GossipItem[];
  /** IDs of contacts this contact can introduce (referral network). */
  referralNetwork?: string[];
  /** Probability 0-1 that this contact will betray the scout. */
  betrayalRisk?: number;
  /** @deprecated Legacy compatibility only. Use top-level accessAgreements. */
  /** Timed exclusive access to a prospect via a high-trust insider. */
  exclusiveWindow?: {
    playerId: string;
    expiresAt: GameDate;
  };
  /** Betrayal temporarily blocks new gossip, referrals, and exclusive access. */
  accessSuspendedUntil?: GameDate;
  /** Whether the contact is dormant (relationship too low to provide intel). */
  dormant?: boolean;
  /**
   * Stable interpretation profile used when this contact supplies evidence.
   * Optional so legacy saves remain neutral instead of inventing a past bias.
   */
  evidencePerspective?: ScoutSourcePerspective;
}

// =============================================================================
// CONTACT INTEL
// =============================================================================

/**
 * A piece of hidden intelligence shared by a contact about a player.
 * Keyed by playerId in the `contactIntel` GameState record.
 */
export interface HiddenIntel {
  playerId: string;
  attribute: HiddenAttribute;
  /** Human-readable hint — worded as a scout's note, not a raw number. */
  hint: string;
  /**
   * 0–1: how reliable this intel is.
   * Determined by the contact's own reliability stat, not shown directly.
   */
  reliability: number;
  /** Contact attribution for comparing this claim with first-hand evidence. */
  sourceContactId?: string;
  sourceName?: string;
  /** Game date when the claim was recorded. Missing means legacy/unknown recency. */
  recordedWeek?: number;
  recordedSeason?: number;
  /** Sanitized, player-visible claim. Never contains hidden player truth values. */
  evidenceClaim?: ScoutEvidenceClaim;
}

// =============================================================================
// EXPLAINABLE SOURCE PERSPECTIVES
// =============================================================================

export type ScoutEvidenceCategory =
  | PlayerAttribute
  | JudgmentCategory
  | "readiness"
  | "adaptability"
  | "durability";

export type ScoutEvidenceDirection = "positive" | "mixed" | "negative";

export type ScoutReferenceLens =
  | "developmentCeiling"
  | "immediateImpact"
  | "dataProjection"
  | "regionalFit"
  | "characterContext"
  | "marketOpportunity";

export type ScoutRiskTolerance = "cautious" | "balanced" | "bold";

export type SourceReliabilityBand =
  | "unproven"
  | "developing"
  | "established"
  | "trusted";

export interface ScoutSourceBias {
  category: ScoutEvidenceCategory;
  /** Bounded interpretation adjustment in [-0.12, 0.12]. */
  adjustment: number;
}

/** A stable actor-level lens. It changes interpretation, never player truth. */
export interface ScoutSourcePerspective {
  actorId: string;
  actorKind: "playerScout" | "npcScout" | "contact";
  lens: ScoutReferenceLens;
  riskTolerance: ScoutRiskTolerance;
  reliabilityBand: SourceReliabilityBand;
  /** At most two bounded biases are stored to keep disagreement legible. */
  biases: ScoutSourceBias[];
}

export type ScoutEvidenceRange =
  | { scale: "attribute20"; low: number; high: number }
  | { scale: "qualitative"; label: "concern" | "uncertain" | "positive" | "strong" };

export interface ScoutEvidenceClaim {
  id: string;
  playerId: string;
  sourceId: string;
  sourceName: string;
  sourceKind: "liveObservation" | "npcScout" | "contact";
  category: ScoutEvidenceCategory;
  direction: ScoutEvidenceDirection;
  range: ScoutEvidenceRange;
  /** Player-visible confidence after reliability and recency, in [0, 1]. */
  confidence: number;
  statement: string;
  /** Explains lens, reliability, recency, and likely reason for disagreement. */
  explanation: string;
  recordedWeek?: number;
  recordedSeason?: number;
  perspective: ScoutSourcePerspective;
  calibration: {
    status: "uncalibrated" | "supported" | "challenged";
    note: string;
    reviewedWeek?: number;
    reviewedSeason?: number;
  };
}

