/**
 * A mechanical consequence applied when a narrative event is resolved.
 * Each consequence maps to a specific game state change (reputation, trust,
 * contact relationships, budget, player form, or player market value).
 */
export interface ChainConsequence {
  type: "reputation" | "clubTrust" | "contactRelationship" | "budget" | "form" | "playerValue";
  /** Additive delta for reputation/clubTrust/form; additive for budget; percentage for playerValue. */
  value: number;
  /** Player or contact ID, required for contactRelationship/form/playerValue. */
  targetId?: string;
  /** Human-readable description of why this consequence occurred. */
  description: string;
}

export interface NarrativeEvent {
  id: string;
  type: NarrativeEventType;
  week: number;
  season: number;
  title: string;
  description: string;
  /** IDs of related entities (players, clubs, contacts). */
  relatedIds: string[];
  /** Whether this event has been acknowledged by the player. */
  acknowledged: boolean;
  /** Optional choices the player can make in response. */
  choices?: {
    label: string;
    effect: string;
    /** Player-facing costs and opportunity costs visible before selection. */
    knownTradeoffs?: string[];
  }[];
  /** Index of the choice the player selected (undefined = no choice made). */
  selectedChoice?: number;
  /** Number of weeks the offer remains open after it is generated. */
  decisionDeadlineWeeks?: number;
  /** Explicit timeout choice; omitted means the decision cannot auto-select. */
  defaultChoiceIndex?: number;
  /** Definition ID from the trait-sensitive scouting special-event deck. */
  specialEventId?: string;

  /** Storyline instance that produced this event, when applicable. */
  storylineId?: string;
  /** Zero-based stage within the producing storyline. */
  storylineStage?: number;

  // --- Event Chain fields (F2) ---

  /** Links events that belong to the same narrative chain. */
  chainId?: string;
  /** 1-based position within the chain (1, 2, 3...). */
  chainStep?: number;
  /** ID of the event that triggered this chain continuation. */
  parentEventId?: string;
  /** Absolute week when the follow-up event should fire. */
  followUpWeek?: number;
  /** Escalation level: 0=normal, 1=warning, 2=critical. */
  escalationLevel?: number;
  /** Whether this chain event has been resolved/concluded. */
  resolved?: boolean;
  /** Mechanical consequences applied when this event is resolved. */
  consequences?: ChainConsequence[];
}

