  /** History of transactions. */
  transactions: {
    week: number;
    season: number;
    amount: number;
    description: string;
    /** Opening principal is balance-sheet state, not earned career income. */
    kind?: "openingBalance";
    /** Stable audit/idempotency key for movements and zero-value contract events. */
    referenceId?: string;
    /** Player-facing classification used by summaries and audit checks. */
    category?: "salary" | "clientRevenue" | "placement" | "operatingCost" | "debt" | "asset" | "bonus" | "opening";
    counterpartyId?: string;
  }[];
  /**
   * Monotonic ordinal for player-triggered financial actions. It is persisted
   * so repeated actions in one week remain unique and save/reload deterministic.
   */
  actionSequence?: number;
  /** 5-slot equipment loadout and owned items. */
  equipment?: EquipmentInventory;

  // --- Economics Revamp Fields ---

  /** Career path this financial record tracks. */
  careerPath: CareerPath;
  /** Independent tier (only for independent path). */
  independentTier?: IndependentTier;

  // Revenue tracking
  reportSalesRevenue: number;
  placementFeeRevenue: number;
  retainerRevenue: number;
  consultingRevenue: number;
  sellOnRevenue: number;
  bonusRevenue: number;

