  employees: AgencyEmployee[];
  /** Employee scouting leads kept separate from player-authored reports. */
  staffWorkProducts: StaffScoutingWorkProduct[];
  /** Bounded review queue and recent consumption audit for agency analysts. */
  analystReviews: AnalystReviewArtifact[];
  /** Last employee lifecycle tick, preventing duplicate manual/batch processing. */
  lastEmployeeEconomicsWeek?: { week: number; season: number };
  lifestyle: LifestyleConfig;
  completedCourses: string[];
  activeEnrollment?: CourseEnrollment;
  ownedVehicle?: { name: string; value: number; travelBonus: number };

  // Pending offers (generated weekly, accepted/declined by player)
  pendingRetainerOffers: RetainerContract[];
  pendingConsultingOffers: ConsultingContract[];

  // Market state
  marketTemperature: MarketTemperature;
  activeEconomicEvents: EconomicEvent[];

  // --- Agency overhaul fields ---
  clientRelationships: ClientRelationship[];
  pendingEmployeeEvents: EmployeeEvent[];
  satelliteOffices: SatelliteOffice[];
  awards: AwardRecord[];

  // --- B2: Economy / Loans ---
  /** @deprecated Legacy debt collection migrated into `activeLoan`. */
  loans: BusinessLoan[];
  /** Starter bonus tracking for new career onboarding. */
  starterBonus: StarterBonus;

  // --- B9: Specialization Income ---
  /**
   * Specialization income bonus/penalty applied to the last monthly income cycle.
   * Positive = bonus, negative = penalty. Purely informational for the UI.
   */
  specBonusApplied?: number;
  /**
   * Tier 3+ specialization unique income earned per month.
   * Tracks academy advisory, transfer window bonuses, regional expertise fees, etc.
   */
  specUniqueIncome?: number;
  /**
   * Youth Scout tier 3+: number of active academy partnerships (max 3).
   * Each pays 500/month.
   */
