// =============================================================================
// FIRST-TEAM SCOUTING SYSTEM
// =============================================================================

/**
 * A directive from a club manager specifying a transfer target profile.
 * Generated at season start and updated mid-season during transfer windows.
 */
export interface ManagerDirective {
  id: string;
  clubId: string;
  managerId: string;
  /** The position the manager wants to strengthen. */
  position: Position;
  /** Priority: higher = more urgently needed. */
  priority: "low" | "medium" | "high" | "critical";
  /** Budget allocated for this position (subset of club budget). */
  budgetAllocation: number;
  /** Age range the manager prefers. */
  ageRange: [number, number];
  /** Minimum CA star rating acceptable. */
  minCAStars: number;
  /** Key attributes the manager values for this role. */
  keyAttributes: PlayerAttribute[];
  /** Reports submitted against this directive. */
  submittedReportIds: string[];
  /** Whether this directive has been fulfilled (player signed). */
  fulfilled: boolean;
  /** Season this directive was issued. */
  season: number;
  /** Optional tactical notes from the manager. */
  tacticalNotes?: string;
  /** The tactical role the manager wants for this position. */
  preferredRole?: PlayerRole;
}

/**
 * Club review state for a first-team report. Report submission may create only
 * the non-terminal review states. `signed` and `loanSigned` are retained for
 * legacy saves and may be written only after an authoritative movement event.
 */
export type ClubResponseType =
  | "ignored"        // Report doesn't match any directive
  | "interested"     // Added to shortlist
  | "trial"          // Club arranges a trial match
  | "doesNotFit"     // Tactical mismatch
  | "tooExpensive"   // Over budget
  | "signed"         // Authoritative transfer movement completed
  | "loanSigned";    // Authoritative loan-start movement completed

export interface ClubResponse {
  reportId: string;
  directiveId?: string;
  response: ClubResponseType;
  feedback: string;
  /** Reputation delta from this response. */
  reputationDelta: number;
  /** Week the response was given. */
  week: number;
  season: number;
}

// =============================================================================
// TRANSFER TRACKER (B10)
// =============================================================================

/**
 * Narrative reasons for why a transfer succeeded or failed.
 * Determined by the transfer tracker when classifying outcomes at season-end.
 */
export type TransferOutcomeReason =
  | "injury"
  | "tacticalMismatch"
  | "characterIssues"
  | "overrated"
  | "perfectFit"
  | "exceededExpectations"
  | "slowAdaptation"
  | "lateBloom"
  /** The player had few recorded first-team opportunities; no cause is inferred. */
  | "limitedOpportunity"
  /** Recorded ratings show sustained strong performance. */
  | "strongPerformance"
  /** Recorded ratings show a dependable, mid-range contribution. */
  | "steadyContribution"
  /** Recorded ratings show sustained performance below the expected benchmark. */
  | "underperformed"
  /** The player is no longer contracted to the destination club. */
  | "movedOn"
  /** The player's retirement is recorded in canonical world state. */
  | "retired"
  /** The simulation cannot yet support a causal explanation. */
  | "insufficientEvidence";

/**
 * Classification of a transfer outcome based on player performance.
 */
export type TransferOutcome = "hit" | "decent" | "flop";

export type TransferMovementStatus =
  | "atDestination"
  | "loanedFromDestination"
  | "movedOn"
  | "unattached"
  | "retired";

export type TransferEvidenceLevel = "none" | "limited" | "sufficient";

/**
 * Immutable, observable evidence captured for one completed season after a
 * transfer. A rating row is an appearance; minutes and starts are counted only
 * when the match engine explicitly recorded them.
 */
export interface TransferSeasonParticipation {
  season: number;
  /** Fixture-derived final week for this competition season. */
  seasonLength: number;
  /** Played destination-club fixtures after the transfer date. */
  teamMatches: number;
  appearances: number;
  /** Starts explicitly marked by the match engine. */
  starts: number;
  /** Sum of explicitly recorded minutes. Undefined when none are available. */
  minutesPlayed?: number;
  /** Appearances whose exact minutes were not recorded. */
  appearancesWithoutMinutes: number;
  /** Average of canonical match ratings for recorded appearances. */
  avgMatchRating?: number;
  /** Dated post-transfer injury incidents beginning in this season. */
  injuryIncidents: number;
  /** Recovery weeks attached to those incidents; not an invented absence. */
  recordedInjuryWeeks: number;
  movementStatus: TransferMovementStatus;
  evidenceLevel: TransferEvidenceLevel;
}

/**
 * A record tracking a player's transfer and subsequent performance.
 * Created when a transfer occurs for a player the scout has reported on.
 * Updated at end-of-season with outcome classification and narrative reason.
 */
export interface TransferRecord {
  /** Unique identifier for this transfer record. */
  id: string;
  /** The player who was transferred. */
  playerId: string;
  /** The scout who recommended the player (player scout ID). */
  scoutId: string;
  /** Club the player transferred from. */
  fromClubId: string;
  /** Club the player transferred to. */
  toClubId: string;
  /** Transfer fee paid. */
  fee: number;
  /** Week the transfer occurred. */
  transferWeek: number;
  /** Season the transfer occurred. */
  transferSeason: number;
  /** The conviction level from the scout's original report. */
  scoutConviction: ConvictionLevel;
  /** Report followed for predictive accountability; this alone does not prove it caused the transfer. */
  reportId: string;
  /** Player's CA at the time of transfer. */
  caAtTransfer: number;
  /** Player's current CA (updated each season). */
  currentCA?: number;
  /** Number of seasons since the transfer. */
  seasonsSinceTransfer: number;
  /** Canonical appearances accumulated from persisted match participation. */
  appearances?: number;
  /** Idempotent observable participation ledger, one entry per completed season. */
  seasonParticipation?: TransferSeasonParticipation[];
  /** Classified outcome once enough data exists. */
  outcome?: TransferOutcome;
  /** Narrative reason for the outcome. */
  outcomeReason?: TransferOutcomeReason;
  /** Whether scout accountability has been applied for this record. */
  accountabilityApplied: boolean;
  /** Average match rating from real match data (1.0-10.0), when available. */
  avgMatchRating?: number;
  /** Quality of the observable evidence behind the current classification. */
  outcomeEvidenceLevel?: TransferEvidenceLevel;
  /** Player-facing evidence statements; never hidden ability or invented causes. */
  outcomeEvidence?: string[];
}

/**
 * System fit analysis result — how well a player matches a club's tactical system.
 * Generated by the first-team perk system.
 */
export interface SystemFitResult {
  playerId: string;
  clubId: string;
  /** Overall fit score 0-100. */
  overallFit: number;
  /** Position compatibility score 0-100. */
  positionFit: number;
  /** How well player attributes align with club play style 0-100. */
  styleFit: number;
  /** Age bracket appropriateness 0-100. */
  ageFit: number;
  /** Role suitability score 0-100. */
  roleFit: number;
  /** Tactical style compatibility score 0-100. */
  tacticalFit: number;
  /** Suggested best role for the player at this club. */
  suggestedRole?: PlayerRole;
  /** Key strengths matching system. */
  fitStrengths: string[];
  /** Areas of concern. */
  fitWeaknesses: string[];
}

